// Extract explained search parameters
const query = $input.item.json.query;
const limit = $input.item.json.limit || 5;
const minScore = $input.item.json.min_score || 0.7;
const conversationId = $input.item.json.conversation_id;
const userId = $input.item.json.user_id;

if (!query) {
  throw new Error('query is required');
}

return {
  query,
  limit,
  minScore,
  conversationId,
  userId,
  timestamp: new Date().toISOString()
};

// Format explained search results for MS Teams (admin view)
const results = $input.item.json.results || [];
const metadata = $input.item.json.metadata || {};

let message = `**🔍 Explained Search Results (Admin)**\n\n`;
message += `Query: "${metadata.query || 'N/A'}"\n`;
message += `Total Results: ${metadata.total_results || 0}\n\n`;

if (results.length === 0) {
  message += '⚠️ No matching documents found.\n';
} else {
  results.forEach((result, index) => {
    message += `**${index + 1}. ${result.file_name || 'Unknown'}**\n`;
    message += `📄 Final Score: ${(result.score || 0).toFixed(4)}\n\n`;

    // Show score breakdown
    if (result.explanation) {
      const exp = result.explanation;
      message += `**Score Breakdown:**\n`;
      message += `  • Semantic Similarity: ${(exp.semantic_score || 0).toFixed(4)}\n`;
      message += `  • Quality Boost: ${(exp.quality_boost || 0).toFixed(4)}\n`;
      message += `  • Recency Factor: ${(exp.recency_factor || 0).toFixed(4)}\n`;
      message += `  • Term Frequency Boost: ${(exp.tf_boost || 0).toFixed(4)}\n\n`;

      if (exp.matching_terms && exp.matching_terms.length > 0) {
        message += `  • Matching Terms: ${exp.matching_terms.join(', ')}\n`;
      }
      message += '\n';
    }

    if (result.text) {
      const preview = result.text.substring(0, 100);
      message += `${preview}${result.text.length > 100 ? '...' : ''}\n`;
    }

    message += '\n---\n\n';
  });
}

return {
  message,
  conversation_id: $input.item.json.conversation_id
};

// Non-admin access denied
return {
  message: '⛔ Access denied. The /search-explain command is restricted to administrators only.',
  conversation_id: $input.item.json.conversation_id
};

// Return formatted response
return {
  json: {
    success: true,
    message: $json.message,
    conversation_id: $json.conversation_id
  }
};
